# Create article no auth
POST {{host}}/api/articles
{
  "article": {
    "title": "No Auth Article",
    "description": "test",
    "body": "test"
  }
}
HTTP 401
[Asserts]
jsonpath "$.errors.token[0]" == "is missing"

