  "article": {
    "title": "Dup Title {{uid}}",
    "description": "second",
    "body": "second"
  }
}
HTTP 201
[Captures]
slug2: jsonpath "$.article.slug"
[Asserts]
jsonpath "$.article.slug" != {{slug1}}

